#include <fstream>
#include <unordered_map>
#include <string>

void write_huffman_dictionary(std::ofstream &outfile, const std::unordered_map<unsigned char, std::string> &huffman_codes) {
    // Write the number of unique characters
    unsigned char dict_size = static_cast<unsigned char>(huffman_codes.size());
    outfile.write(reinterpret_cast<const char*>(&dict_size), sizeof(dict_size));

    // Write each character and its code
    for (const auto& pair : huffman_codes) {
        unsigned char character = pair.first;
        const std::string& code = pair.second;

        // Write the character
        outfile.write(reinterpret_cast<const char*>(&character), sizeof(character));

        // Write the code length
        unsigned char code_length = static_cast<unsigned char>(code.length());
        outfile.write(reinterpret_cast<const char*>(&code_length), sizeof(code_length));

        // Write the code bits
        if (code_length > 0) {
            char buffer = 0;
            int bit_pos = 0;

            for (char bit : code) {
                if (bit == '1') {
                    buffer |= (1 << (7 - bit_pos));
                }
                bit_pos++;

                if (bit_pos == 8) {
                    outfile.write(&buffer, sizeof(char));
                    buffer = 0;
                    bit_pos = 0;
                }
            }

            // Write remaining bits if any
            if (bit_pos > 0) {
                outfile.write(&buffer, sizeof(char));
            }
        }
    }
}

int main() {
    std::unordered_map<unsigned char, std::string> test_codes = {
        {'a', "010"},
        {'b', "11"},
        {'c', "00"}
    };

    std::ofstream test_file("test.bin", std::ios::binary);
    write_huffman_dictionary(test_file, test_codes);
    test_file.close();

    return 0;
}

